<script>let { data, form } = $props();</script>
<svelte:head><title>Review Drafts — Wiki Viki</title></svelte:head>
<div class="form-page"><section class="wiki-form"><header class="document-header"><h1>Review Drafts</h1><div class="document-meta">Draft → Human Review → Publish</div></header>
